<script setup lang="ts">
import { computed } from 'vue'
import { bytes, metric, milliseconds, timingSource, type OperationsHealth } from '../../operations'
import { dateTime } from '../../types'
import MetricGrid from './MetricGrid.vue'
import OperationsFreshness from './OperationsFreshness.vue'
import Panel from '../../components/ui/Panel.vue'
import Tag from '../../components/ui/Tag.vue'
const props=defineProps<{ data: OperationsHealth }>()
const values=computed<[string,string][]>(()=>{const d=props.data;return [['采集队列',`${d.queue.size} 条 / ${bytes(d.queue.bytes)}`],['累计丢弃',metric(d.telemetry.dropped)],['队列丢弃',metric(d.queue.dropped)],['最旧队列年龄',milliseconds(d.queue.oldestAgeMs)],['监控存储',d.storage.available?`${bytes(d.storage.bytes)} / ${bytes(d.storage.budgetBytes)}`:'不可用'],['运行堆内存',`${bytes(d.runtime.heapUsedBytes)} / ${bytes(d.runtime.heapMaxBytes)}`],['GC 次数 / 累计时间',`${d.runtime.gcCount} / ${d.runtime.gcTimeMs} ms`],['连接池使用',`${metric(d.runtime.connectionsActive)} / ${metric(d.runtime.connectionsMax)}`],['等待连接',metric(d.runtime.connectionsPending)],['监控自身失败',metric(d.telemetry.monitorFailures??null)],['已接收',metric(d.telemetry.accepted)],['客户端报告 / 仅后端',`${d.telemetry.clientReported} / ${d.telemetry.serverOnly}`],['实时转写连接',metric(d.asr.connections)],['转写错误',metric(d.asr.errors)],['首段字幕样本',metric(d.asr.sampleCount??null)],['首段字幕 P95',milliseconds(d.asr.firstTranscriptP95Ms)],['Prometheus',d.prometheus.available?'可用':'不可用'],['明细可查询起点',d.storage.detailAvailableSince?dateTime(d.storage.detailAvailableSince):'未知'],['趋势可查询起点',d.storage.trendAvailableSince?dateTime(d.storage.trendAvailableSince):'未知']]})
</script>
<template><section class="stack"><h2 class="section-label">健康与容量</h2><MetricGrid :values="values" /><p class="business-caption">明细保留 {{ data.storage.retentionDays }} 天，趋势保留 90 天。数据库显示的预算用于清理，是软预算；Prometheus 1 GB 保留设置不包括全部 WAL 和内存 head，不代表总容量硬配额。允许显式丢弃；监控自身失败与丢弃分别计数。</p></section><Panel title="转写统计范围" class="reveal business-panel" aria-label="转写统计范围"><OperationsFreshness :updated-at="data.asr.updatedAt" :stale="data.asr.stale ?? true" /><p class="business-caption">连接数为实时读数；错误、首段字幕 P95 与样本数统计最近 {{ data.asr.hours ?? '未知' }} 小时。测量来源：{{ timingSource(data.asr.source) }}。{{ data.asr.sampleCount !== undefined && data.asr.sampleCount !== null && data.asr.sampleCount <20 ? '低样本，延迟指标仅供参考。' : '' }}</p></Panel><Panel title="页面提醒" class="reveal business-panel" aria-label="页面提醒"><p class="business-caption">请求比例与耗时类提醒须达到最小样本并持续超阈值；连接、存储及服务健康提醒不依赖请求样本数。仅在此页面展示。</p><article v-for="a in data.alerts" :key="a.id" class="alert-group"><strong>{{ a.message }}</strong><Tag :tone="a.state === 'firing' ? 'red' : 'lime'">{{ a.state === 'pending' ? '持续观察' : a.state === 'firing' ? '触发中' : '已恢复' }}</Tag><p class="business-caption">级别 {{ a.severity }} · 自 {{ dateTime(a.since) }}</p></article><p v-if="!data.alerts.length" class="business-caption">暂无触发的页面提醒。</p></Panel></template>
